package org.eternalself.umbrielremote;
import android.app.AlertDialog;
import android.graphics.*;
import android.text.TextUtils;
import android.util.Base64;
import android.view.*;
import android.widget.*;
import org.json.*;

/** One event-driven media view. Controls always target the player whose metadata is displayed. */
final class MediaPanel extends LinearLayout {
    final RemoteDashboard dashboard;final UiDesign ui;
    final ImageView cover;final TextView title,artist,origin,playback,volumeText;final Button previous,play,next,choosePlayer,mute,output;final SeekBar volume;
    JSONArray players=new JSONArray(),outputs=new JSONArray();JSONObject selected=new JSONObject();String preferred="",artKey="";boolean active,disposed,busy,again,changing,dragging;
    MediaPanel(RemoteDashboard dashboard){
        super(dashboard.activity);this.dashboard=dashboard;ui=dashboard.ui;preferred=dashboard.activity.getPreferences(0).getString("mediaPlayer","");setOrientation(VERTICAL);setPadding(ui.dp(20),ui.dp(20),ui.dp(20),ui.dp(20));setBackground(ui.shape(ui.surface,26));setTag("media-panel");
        ui.add(this,ui.label("Reproducción",20,ui.text,true),12);
        LinearLayout track=new LinearLayout(getContext());track.setGravity(Gravity.CENTER_VERTICAL);cover=new ImageView(getContext());cover.setBackground(ui.shape(ui.raised,16));cover.setClipToOutline(true);placeholder();track.addView(cover,new LinearLayout.LayoutParams(ui.dp(80),ui.dp(80)));
        LinearLayout info=ui.column();info.setPadding(ui.dp(14),0,0,0);title=ui.label("Leyendo reproducción…",17,ui.text,true);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);artist=ui.label("",13,ui.muted,false);artist.setMaxLines(2);origin=ui.label("",12,ui.muted,false);origin.setMaxLines(2);info.addView(title);ui.add(info,artist,4);info.addView(origin);track.addView(info,new LinearLayout.LayoutParams(0,-2,1));ui.add(this,track,12);
        playback=ui.label("",12,ui.muted,false);playback.setTag("media-status");ui.add(this,playback,8);
        choosePlayer=ui.button("Elegir reproductor…",false);choosePlayer.setVisibility(GONE);choosePlayer.setOnClickListener(v->selectPlayer());ui.add(this,choosePlayer,12);
        previous=transport("Pista anterior","previous");play=transport("Reproducción no disponible","play");play.setTag("media-play");next=transport("Pista siguiente","next");dashboard.row(this,previous,play,next);previous.setOnClickListener(v->act("previous"));next.setOnClickListener(v->act("next"));play.setOnClickListener(v->act(selected.optString("status").equals("Playing")?"pause":"play"));
        volumeText=ui.label("Volumen · leyendo…",14,ui.muted,false);ui.add(this,volumeText,4);volume=new SeekBar(getContext());volume.setMax(100);volume.setEnabled(false);ui.add(this,volume,12);
        volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int value,boolean user){if(user)volumeText.setText("Volumen · "+value+" %");}public void onStartTrackingTouch(SeekBar bar){dragging=true;}public void onStopTrackingTouch(SeekBar bar){dragging=false;dashboard.request("action",dashboard.object("action","noctalia.volume-set","args",new JSONArray().put(bar.getProgress())),r->{if(!r.optBoolean("ok"))dashboard.result(r);refresh();});}});
        mute=ui.button("Silenciar",false);mute.setEnabled(false);mute.setOnClickListener(v->dashboard.request("action",dashboard.object("action","noctalia.volume-mute","args",new JSONArray()),r->{if(!r.optBoolean("ok"))dashboard.result(r);refresh();}));ui.add(this,mute,12);
        output=ui.button("Salida de audio · leyendo…",false);output.setTag("audio-output");output.setEnabled(false);output.setOnClickListener(v->{if(outputs.length()==0)refresh();else chooseOutput();});ui.add(this,output,8);ui.add(this,ui.label("La salida se aplica a los sonidos actuales y a los siguientes.",12,ui.muted,false),0);
        if(!dashboard.features.optBoolean("media")){title.setText("Actualiza Umbriel Connect en la PC");playback.setText("El receptor anterior no publica el estado del reproductor.");}
    }
    Button transport(String label,String icon){Button b=ui.button("",icon.equals("play"));b.setContentDescription(label);b.setCompoundDrawables(null,ui.icon(icon,icon.equals("play")?ui.onAccent:ui.text,24),null,null);b.setEnabled(false);return b;}
    void placeholder(){cover.setScaleType(ImageView.ScaleType.CENTER_INSIDE);cover.setPadding(ui.dp(20),ui.dp(20),ui.dp(20),ui.dp(20));cover.setImageDrawable(ui.icon("music",ui.muted,32));cover.setContentDescription("Sin carátula disponible");}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();resume();}
    @Override protected void onDetachedFromWindow(){pause();super.onDetachedFromWindow();}
    void resume(){if(disposed||active||!dashboard.features.optBoolean("media"))return;active=true;dashboard.request("media-watch",dashboard.object("enabled",true),r->{});refresh();}
    void pause(){if(!active)return;active=false;dashboard.request("media-watch",dashboard.object("enabled",false),r->{});}
    void dispose(){pause();disposed=true;}
    void refresh(){if(!active||disposed)return;if(busy||changing){again=true;return;}busy=true;
        dashboard.request("media-state",new JSONObject(),r->{if(!live()){busy=false;return;}JSONObject data=r.optJSONObject("value");if(!r.optBoolean("ok")||data==null){players=new JSONArray();chooseTrack();title.setText("Reproducción no disponible");playback.setText("Vuelve a abrir Sonido para actualizar.");readOutputs();return;}
            players=data.optJSONArray("players");if(players==null)players=new JSONArray();chooseTrack();readArt(()->readOutputs());
        });
    }
    boolean live(){return !disposed&&active;}
    void finish(){busy=false;if(again&&live()){again=false;refresh();}}
    void chooseTrack(){selected=new JSONObject();for(int i=0;i<players.length();i++){JSONObject p=players.optJSONObject(i);if(p!=null&&(selected.length()==0||p.optString("id").equals(preferred))){selected=p;if(p.optString("id").equals(preferred))break;}}
        String state=selected.optString("status");title.setText(players.length()==0?"No hay un reproductor abierto":selected.optString("title").isEmpty()?"Sin título":selected.optString("title"));artist.setText(selected.optString("artist"));String source=selected.optString("source"),site=selected.optString("origin");origin.setText(source+(site.isEmpty()?"":" · "+site));cover.setContentDescription("Carátula de "+title.getText());
        playback.setText(state.equals("Playing")?"En reproducción":state.equals("Paused")?"En pausa":"Sin reproducción");play.setContentDescription(state.equals("Playing")?"Pausar":"Reproducir");play.setCompoundDrawables(null,ui.icon(state.equals("Playing")?"pause":"play",ui.onAccent,24),null,null);play.setEnabled(!changing&&selected.optBoolean(state.equals("Playing")?"canPause":"canPlay"));previous.setEnabled(!changing&&selected.optBoolean("canPrevious"));next.setEnabled(!changing&&selected.optBoolean("canNext"));choosePlayer.setVisibility(players.length()>1?VISIBLE:GONE);choosePlayer.setText(source+" · cambiar reproductor…");}
    void readArt(Runnable nextStep){String key=selected.optString("artKey");if(key.equals(artKey)){nextStep.run();return;}artKey=key;placeholder();if(key.isEmpty()){nextStep.run();return;}
        String player=selected.optString("id");dashboard.request("media-art",dashboard.object("player",player,"key",key),r->{if(!live())return;JSONObject value=r.optJSONObject("value");if(r.optBoolean("ok")&&value!=null&&key.equals(artKey))try{String encoded=value.optString("jpeg");if(encoded.length()<=140000){byte[] bytes=Base64.decode(encoded,Base64.NO_WRAP);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth>0&&bounds.outHeight>0&&bounds.outWidth<=256&&bounds.outHeight<=256){Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null){cover.setPadding(0,0,0,0);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setImageBitmap(bitmap);cover.setContentDescription("Carátula de "+title.getText());}}}}catch(IllegalArgumentException ignored){}nextStep.run();});}
    void readOutputs(){if(!live())return;if(!dashboard.features.optBoolean("audioOutputs")){output.setText("Salidas no disponibles en este receptor");readVolume();return;}
        dashboard.request("audio-outputs",new JSONObject(),r->{if(!live())return;JSONObject value=r.optJSONObject("value");outputs=value==null?new JSONArray():value.optJSONArray("outputs");if(outputs==null)outputs=new JSONArray();String name="Elegir salida…";for(int i=0;i<outputs.length();i++){JSONObject item=outputs.optJSONObject(i);if(item!=null&&item.optBoolean("default"))name="Salida · "+item.optString("name");}output.setText(r.optBoolean("ok")?name:"Reintentar salidas de audio…");output.setEnabled(!changing);readVolume();});}
    void showVolume(JSONObject state){if(!dragging)volume.setProgress(state.optInt("volume"));volumeText.setText("Volumen · "+state.optInt("volume")+" %"+(state.optBoolean("muted")?" · silenciado":""));mute.setText(state.optBoolean("muted")?"Activar audio":"Silenciar");mute.setEnabled(true);volume.setEnabled(true);}
    void readVolume(){for(int i=0;i<outputs.length();i++){JSONObject item=outputs.optJSONObject(i);if(item!=null&&item.optBoolean("default")&&item.has("volume")&&item.has("muted")){showVolume(item);finish();return;}}dashboard.request("audio-state",new JSONObject(),r->{if(!live())return;JSONObject state=r.optJSONObject("value");if(r.optBoolean("ok")&&state!=null){showVolume(state);}else volumeText.setText("Volumen actual no disponible");finish();});}
    void act(String op){if(changing||selected.length()==0)return;changing=true;chooseTrack();dashboard.request("media-action",dashboard.object("player",selected.optString("id"),"action",op),r->{changing=false;if(!r.optBoolean("ok"))dashboard.result(r);refresh();});}
    void selectPlayer(){final JSONArray choices=players;String[] labels=new String[choices.length()+1];labels[0]="Automático · en reproducción";for(int i=0;i<choices.length();i++)labels[i+1]=choices.optJSONObject(i).optString("source");new AlertDialog.Builder(getContext()).setTitle("Reproductor de la PC").setItems(labels,(dialog,index)->{preferred=index==0?"":choices.optJSONObject(index-1).optString("id");dashboard.activity.getPreferences(0).edit().putString("mediaPlayer",preferred).apply();artKey="";chooseTrack();refresh();}).setNegativeButton("Cancelar",null).show();}
    void chooseOutput(){final JSONArray choices=outputs;String[] names=new String[choices.length()];int checked=-1;for(int i=0;i<names.length;i++){JSONObject p=choices.optJSONObject(i);names[i]=p.optString("name");if(p.optBoolean("default"))checked=i;}
        new AlertDialog.Builder(getContext()).setTitle("Salida de audio de la PC").setSingleChoiceItems(names,checked,(dialog,index)->{dialog.dismiss();String id=choices.optJSONObject(index).optString("id");changing=true;output.setEnabled(false);dashboard.request("audio-output-set",dashboard.object("id",id),r->{changing=false;if(r.optBoolean("ok")&&r.optJSONObject("value")!=null&&r.optJSONObject("value").optInt("failed")>0)dashboard.status.accept("Salida cambiada; algunas aplicaciones mantienen su salida anterior.");else dashboard.result(r);refresh();});}).setNegativeButton("Cancelar",null).show();}
}
